const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let view='dashboard', libraryCache=[], settingsCache=null, entityMode={scenes:'library',performers:'library',studios:'library'};
let entityLibraryCache={scenes:null,performers:null,studios:null},entityCursors={scenes:null,performers:null,studios:null},entityTotals={scenes:null,performers:null,studios:null},entityPageSize={scenes:100,performers:60,studios:60};
let entityLibraryQuery={scenes:'',performers:'',studios:''},entityPrefetch=new Map();
let mediaLibraryRows=[],mediaLibraryCursor=null,mediaLibraryHasMore=false,mediaLibraryPrefetch=new Map();
let liveQueueTimer=null,liveQueueBusy=false,liveQueueSnapshot={tracked:[],clients:{}};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=v=>v?new Date(v).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}):'—';
const bytes=n=>{if(!n&&n!==0)return'—';let u=['B','KB','MB','GB','TB'],i=0,x=Number(n);while(x>=1024&&i<u.length-1){x/=1024;i++}return`${x.toFixed(i>2?2:i?1:0)} ${u[i]}`};
const durationText=n=>{if(n==null)return'—';let x=Math.max(0,Math.floor(Number(n))),h=Math.floor(x/3600),m=Math.floor((x%3600)/60),sec=x%60;return h?`${h}:${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`:`${m}:${String(sec).padStart(2,'0')}`};
const api=async(path,opts={})=>{let h={'Content-Type':'application/json',...(opts.headers||{})};let r=await fetch(path,{...opts,headers:h});if(r.status===204)return null;let text=await r.text(),data;try{data=JSON.parse(text)}catch{data=text}if(!r.ok)throw new Error(data?.detail||data||`${r.status}`);return data};
const patch=body=>({method:'PATCH',body:JSON.stringify(body)}), post=body=>({method:'POST',body:body===undefined?undefined:JSON.stringify(body)}), put=body=>({method:'PUT',body:JSON.stringify(body)});
function notify(msg,type='info'){let n=document.createElement('div');n.className=`notice ${type}`;n.textContent=msg;$('#app').prepend(n);setTimeout(()=>n.remove(),4500)}
function nav(){$$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view))}
function pageHead(title,sub,actions=''){return `<div class="pagehead"><div><h1>${esc(title)}</h1></div><div class="actions">${actions}</div></div>`}
function empty(msg){return `<div class="empty">${esc(msg)}</div>`}
function sceneImage(x){return x.image_url||x.back_image_url||''}
function modal(title,html){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modal').classList.add('open')}
$('#closeModal').onclick=()=>$('#modal').classList.remove('open');$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').classList.remove('open')};

async function boot(){
  $('#hostLabel').textContent=location.hostname||'local';
  $('#nav').onclick=e=>{let b=e.target.closest('button[data-view]');if(!b)return;view=b.dataset.view;nav();render()};
  $('#queueShortcut').onclick=()=>{view='activity';nav();render()};
  $('#globalSearch').onsubmit=e=>{e.preventDefault();let q=$('#globalSearchInput').value.trim();if(q.length<2)return;view='scenes';entityMode.scenes='search';nav();renderEntities('scenes',q)};
  try{let s=await api('/api/system/status');$('#versionSide').textContent=`v${s.version} · Local`}catch(e){$('#onlineText').textContent='Offline';$('#statusDot').style.background='#b91c2b'}
  await updateChrome();render();
}
async function updateChrome(){
  try{
    let [a,d]=await Promise.all([api('/api/activity/queue').catch(()=>({tracked:[]})),api('/api/system/diskspace').catch(()=>[])]);
    $('#queueBadge').textContent=(a.tracked||[]).length;
    let x=d.find(i=>i.exists&&i.total_bytes)||d.find(i=>i.exists);
    if(x&&x.total_bytes){let pct=Math.round((x.used_bytes/x.total_bytes)*100);$('#storageBar').style.width=`${pct}%`;$('#storageUsed').textContent=`${bytes(x.used_bytes)} / ${bytes(x.total_bytes)}`;$('#storagePct').textContent=`${pct}%`}
  }catch{}
}
function stopLiveQueue(){if(liveQueueTimer){clearTimeout(liveQueueTimer);liveQueueTimer=null}liveQueueBusy=false}
async function render(){nav();if(view==='dashboard')return dashboard();if(view==='library')return mediaLibrary();if(['scenes','performers','studios'].includes(view))return renderEntities(view);if(view==='wanted')return wanted();if(view==='activity')return activity();if(view==='calendar')return calendar();if(view==='settings')return settings()}

async function dashboard(){
  $('#app').innerHTML=pageHead('Welcome back','Here’s what’s happening with your library.',`<button class="btn primary" id="addNew">＋ Add New</button>`)+`<div class="stats" id="stats"></div><div class="dashgrid"><div class="panel"><div class="panel-head"><h2>Activity Queue</h2><button class="linkbtn" data-go="activity">View all</button></div><div class="rows" id="queueRows"></div></div><div class="panel"><div class="panel-head"><h2>Recent Activity</h2><button class="linkbtn" data-go="activity">View all</button></div><div class="rows" id="historyRows"></div></div><div class="panel"><div class="panel-head"><h2>Upcoming</h2><button class="linkbtn" data-go="calendar">View calendar</button></div><div class="rows" id="calendarRows"></div></div></div><div class="panel recent"><div class="panel-head"><h2>Recently Added Scenes</h2><button class="linkbtn" data-go="scenes">View library</button></div><div id="recentScenes" style="padding:0 12px 14px"></div></div>`;
  $('#addNew').onclick=()=>{view='scenes';entityMode.scenes='search';nav();renderEntities('scenes')};
  $('#app').onclick=e=>{let b=e.target.closest('[data-go]');if(b){view=b.dataset.go;nav();render()}};
  try{
    let [sys,recent,queue,hist,cal,disk]=await Promise.all([api('/api/system/status'),api('/api/library/scenes/page?limit=8'),api('/api/activity/queue').catch(()=>({tracked:[]})),api('/api/history?limit=8'),api('/api/calendar?limit=5'),api('/api/system/diskspace').catch(()=>[])]);
    let scenes=recent.items||[];libraryCache=scenes;
    let total=0,used=0;disk.filter(x=>x.exists&&x.total_bytes).forEach(x=>{total+=x.total_bytes;used+=x.used_bytes});let pct=total?Math.round(used/total*100):0;
    $('#stats').innerHTML=[['▣','Scenes',sys.library?.scene||0,'Adult library'],['♙','Performers',sys.performers||0,'In library'],['▥','Studios',sys.studios||0,'In library'],['◎','Wanted',sys.wanted||0,'Missing'],['▱','Storage',total?bytes(used):'—',total?`${pct}% of ${bytes(total)}`:'No scene root yet']].map(x=>`<div class="stat"><div class="stat-icon">${x[0]}</div><div><small>${x[1]}</small><strong>${x[2]}</strong><em>${x[3]}</em></div></div>`).join('');
    $('#queueRows').innerHTML=(queue.tracked||[]).slice(0,5).map(x=>`<div class="row"><div class="rowicon">↓</div><div><b>${esc(x.release_title||x.scene_title||'Download')}</b><small>${esc(x.status||'queued')}</small></div><span class="badge soft">${esc(x.status?.slice(0,1)?.toUpperCase()||'Q')}</span></div>`).join('')||`<div class="row"><div class="rowicon">✓</div><div><b>Queue clear</b><small>No active downloads</small></div><span class="check">✓</span></div>`;
    $('#historyRows').innerHTML=hist.slice(0,5).map(x=>`<div class="row"><div class="rowicon">↻</div><div><b>${esc(x.message)}</b><small>${fmtDate(x.created_at)}</small></div><span class="check">✓</span></div>`).join('')||`<div class="row"><div class="rowicon">•</div><div><b>No activity yet</b><small>ScarletX activity will appear here.</small></div></div>`;
    $('#calendarRows').innerHTML=cal.slice(0,5).map(x=>`<div class="row"><div class="rowicon">${new Date(x.date).getDate()}</div><div><b>${esc(x.title)}</b><small>${fmtDate(x.date)}</small></div><span class="badge soft">Scene</span></div>`).join('')||`<div class="row"><div class="rowicon">□</div><div><b>No upcoming releases</b><small>Monitored release dates will appear here.</small></div></div>`;
    $('#recentScenes').innerHTML=scenes.length?sceneTable(scenes.slice(0,8),true):empty('Add your first scene to start building the library.');bindSceneTableActions($('#recentScenes'),true);
  }catch(e){notify(e.message,'error')}
}
function performerLinks(x){
  let rows=x.performers||[];
  return rows.length?`<div class="credit-links">${rows.map(p=>`<button class="person-link" data-performer-link="${esc(p.id||p.tpdb_id||'')}" title="Open performer profile">${esc(p.name||'Performer')}</button>`).join('')}</div>`:'<span class="muted">—</span>';
}
function studioLink(x){let st=x.studio;if(!st)return '<span class="muted">—</span>';let name=typeof st==='string'?st:(st.name||'Studio'),id=typeof st==='object'?(st.id||st.tpdb_id||''):(x.studio_id||'');return id?`<button class="studio-link" data-studio-link="${esc(id)}">${esc(name)}</button>`:esc(name)}
function sceneRowsHtml(rows,inLibrary=false){return rows.map(x=>{let id=x.tpdb_id||x.id,local=inLibrary?x.id:'',hasFile=inLibrary&&(x.has_file||(x.files||[]).length>0);return `<tr data-scene-id="${esc(id)}" data-local-id="${esc(local)}"><td><button class="scene-title" data-scene-detail>${esc(x.title||'Untitled')}</button></td><td>${studioLink(x)}</td><td>${fmtDate(x.release_date)}</td><td>${performerLinks(x)}</td><td><div class="scene-status">${inLibrary?`<span class="state ${x.monitored?'good':'warn'}">${x.monitored?'Monitored':'Not monitored'}</span>${hasFile?'<span class="state good">Downloaded</span>':''}`:`<span class="state ${['Downloaded','Downloading','Queued','Post-processing','Import pending'].includes(x.download_status)?'good':x.download_status==='Failed'?'bad':'warn'}">${esc(x.download_status||'Available')}</span>`}</div></td><td><div class="actions">${(!inLibrary||!x.monitored)?'<button class="btn small primary" data-monitor-scene>Monitor</button>':''}${inLibrary?'<button class="btn small danger" data-remove-scene>Remove</button>':'<button class="btn small" data-scene-detail>Details</button>'}</div></td></tr>`}).join('')}
function sceneTable(rows,inLibrary=false){if(!rows.length)return empty('No scenes found.');return `<div class="tablewrap"><table class="table"><thead><tr><th>Scene</th><th>Studio</th><th>Release</th><th>Performers</th><th>Status</th><th></th></tr></thead><tbody>${sceneRowsHtml(rows,inLibrary)}</tbody></table></div>`}
function bindSceneTableActions(root,inLibrary){
  if(!root)return;root.onclick=async e=>{
    let p=e.target.closest('[data-performer-link]');if(p)return performerProfile(p.dataset.performerLink,null);
    let st=e.target.closest('[data-studio-link]');if(st)return studioProfile(st.dataset.studioLink,null);
    let tr=e.target.closest('tr[data-scene-id]');if(!tr)return;let id=tr.dataset.sceneId,local=tr.dataset.localId;
    let b=e.target.closest('button');if(!b)return;
    try{
      if(b.hasAttribute('data-monitor-scene')){b.disabled=true;b.textContent='Starting…';await api(inLibrary?`/api/library/scenes/${local}/monitor`:`/api/metadata/scenes/${encodeURIComponent(id)}/monitor`,post());b.remove();notify('Monitored. ScarletX is searching and downloading in the background.','ok');return}
      if(b.hasAttribute('data-remove-scene')){if(!confirm('Remove this scene from ScarletX?'))return;await api(`/api/library/scenes/${local}`,{method:'DELETE'});return loadEntityLibrary('scenes')}
      if(b.hasAttribute('data-scene-detail'))return scenePage(id,inLibrary?local:null);
    }catch(err){notify(err.message,'error');b.disabled=false;b.textContent='Monitor'}
  }
}

async function renderEntities(type,forcedQuery=''){
  let mode=entityMode[type];let names={scenes:'Scenes',performers:'Performers',studios:'Studios'};let singular={scenes:'scene',performers:'performer',studios:'studio'}[type];
  $('#app').innerHTML=pageHead(names[type],'')+`<div class="toolbar"><div class="tabs"><button data-mode="library" class="${mode==='library'?'active':''}">Library</button><button data-mode="search" class="${mode==='search'?'active':''}">Add / Search</button></div><form id="entitySearch" class="searchbox"><input class="input" id="entityQ" minlength="2" placeholder="Search ${type}…" value="${esc(forcedQuery)}"></form>${type==='scenes'?`<button class="btn" id="refreshAll">Refresh Library</button>`:''}</div><div id="entityNotice"></div><div class="${type==='scenes'?'':'cardgrid'}" id="entityGrid"></div>`;
  $$('.tabs button').forEach(b=>b.onclick=()=>{entityMode[type]=b.dataset.mode;renderEntities(type)});
  $('#entitySearch').onsubmit=e=>{e.preventDefault();let q=$('#entityQ').value.trim();if(q.length<2)return;if(entityMode[type]==='library')loadEntityLibrary(type,null,false,q);else searchEntity(type,q)};
  if($('#refreshAll'))$('#refreshAll').onclick=async()=>{let rows=await api('/api/library/scenes');for(let x of rows){await api(`/api/library/scenes/${x.id}/refresh`,post())}notify(`Queued refresh for ${rows.length} scenes.`,'ok')};
  if(mode==='library'&&!forcedQuery){let cached=entityLibraryCache[type];if(cached)paintEntityLibrary(type,cached,false);else $('#entityGrid').innerHTML=empty(`Loading ${type}…`);return loadEntityLibrary(type,0,false)}if(forcedQuery)return searchEntity(type,forcedQuery);$('#entityGrid').innerHTML=empty(`Search TPDB to add a ${singular}.`)
}
function paintEntityLibrary(type,data,append=false){
  let rows=data.items||[],grid=$('#entityGrid');if(!grid)return;
  grid.querySelector('.load-more')?.remove();
  if(type==='scenes'){
    if(append&&grid.querySelector('tbody')){grid.querySelector('tbody').insertAdjacentHTML('beforeend',sceneRowsHtml(rows,true));libraryCache.push(...rows)}
    else{libraryCache=[...rows];grid.innerHTML=sceneTable(rows,true);bindSceneTableActions(grid,true)}
  }else{
    if(append&&grid.querySelector('.media-card'))grid.insertAdjacentHTML('beforeend',rows.map(x=>entityCard(type,x,true)).join(''));
    else grid.innerHTML=rows.length?rows.map(x=>entityCard(type,x,true)).join(''):empty(`No ${type} in your library yet.`);
    bindEntityActions(type,true);
  }
  let cache=entityLibraryCache[type]||{items:[]};if(append)cache.items=[...(cache.items||[]),...rows];else cache={...data,items:[...rows]};cache.next_cursor=data.next_cursor;cache.has_more=!!data.has_more;cache.total=data.total??cache.total??rows.length;entityLibraryCache[type]=cache;entityCursors[type]=data.next_cursor||null;entityTotals[type]=cache.total;
  let shown=cache.items.length,total=cache.total;
  if(data.has_more)grid.insertAdjacentHTML('beforeend',`<div class="load-more"><button class="btn" data-load-more="${type}">Load more <span class="muted">(${shown}${total!=null?` of ${total}`:''})</span></button></div>`);
  let more=grid.querySelector('[data-load-more]');if(more)more.onclick=()=>loadEntityLibrary(type,entityCursors[type],true);
}
function entityPageUrl(type,cursor=null,q=''){
  let size=entityPageSize[type];return `/api/library/${type}/page?limit=${size}`+(cursor?`&cursor=${encodeURIComponent(cursor)}`:'')+(q?`&q=${encodeURIComponent(q)}`:'');
}
function prefetchEntityPage(type,cursor,q=''){
  if(!cursor)return;let url=entityPageUrl(type,cursor,q);if(entityPrefetch.has(url))return;
  let run=()=>{if(!entityPrefetch.has(url))entityPrefetch.set(url,api(url).catch(err=>{entityPrefetch.delete(url);throw err}))};
  if('requestIdleCallback'in window)requestIdleCallback(run,{timeout:700});else setTimeout(run,80);
}
async function loadEntityLibrary(type,cursor=null,append=false,q=null){
  try{
    if(q===null)q=entityLibraryQuery[type]||'';if(!append)entityLibraryQuery[type]=q;
    let url=entityPageUrl(type,cursor,q),pending=entityPrefetch.get(url),data=pending?await pending:await api(url);entityPrefetch.delete(url);
    paintEntityLibrary(type,data,append);if(data.has_more&&data.next_cursor)prefetchEntityPage(type,data.next_cursor,q);
  }catch(e){notify(e.message,'error')}
}
async function searchEntity(type,q){
  $('#entityGrid').innerHTML=empty('Searching TPDB…');try{let d=await api(`/api/search/${type}?q=${encodeURIComponent(q)}`);let rows=d.items||d;if(type==='scenes'){$('#entityGrid').innerHTML=sceneTable(rows,false);bindSceneTableActions($('#entityGrid'),false);return}$('#entityGrid').innerHTML=rows.length?rows.map(x=>entityCard(type,x,false)).join(''):empty('No TPDB results found.');bindEntityActions(type,false)}catch(e){$('#entityGrid').innerHTML=empty(e.message)}
}
function entityCard(type,x,inLibrary){
  let id=x.tpdb_id||x.id, img=x.image_url||x.poster_url||x.logo_url||'', title=x.title||x.name||'Untitled',sub=x.aliases||x.description||'';
  let posterClass=type==='performers'?'media-poster performer-poster':'media-poster';
  let cachedImg=type==='performers'?`/api/artwork/performers/${encodeURIComponent(id)}?size=card`:type==='studios'?`/api/artwork/studios/${encodeURIComponent(id)}?size=card`:img;
  return `<article class="media-card ${type==='performers'?'performer-card':type==='studios'?'studio-card':''}" data-id="${esc(id)}" data-local-id="${inLibrary?esc(x.id):''}"><div class="${posterClass}">${img?`<img src="${esc(cachedImg)}" loading="lazy" ${type==='performers'?'data-performer-image title="Open performer profile"':''} onerror="this.remove()">`:''}</div><div class="media-body"><h3>${esc(title)}</h3><p>${esc(typeof sub==='string'?sub:'')}</p><div class="actions">${inLibrary?`<button class="btn small" data-detail>Details</button><button class="btn small danger" data-remove>Remove</button>`:`<button class="btn small primary" data-add>Add & Monitor All</button><button class="btn small" data-remote-detail>Details</button>`}</div></div></article>`
}
function bindEntityActions(type,inLibrary){
  $('#entityGrid').onclick=async e=>{let c=e.target.closest('.media-card');if(!c)return;let b=e.target.closest('button'),id=c.dataset.id,local=c.dataset.localId;
    if(!b&&type==='performers')return performerProfile(id,local||null);
    if(!b&&type==='studios')return studioProfile(id,local||null);
    if(!b)return;
    try{
      if(b.hasAttribute('data-add')){b.disabled=true;b.textContent='Monitoring…';let r=await api(`/api/library/${type}/${encodeURIComponent(id)}`,post({monitored:true}));notify(`Monitor All started${r.job_id?` (job ${r.job_id})`:''}. ScarletX will search and download matching studio scenes.`,'ok');entityMode[type]='library';return renderEntities(type)}
      if(b.hasAttribute('data-remove')){if(!confirm(`Remove this ${type.slice(0,-1)} from ScarletX?`))return;await api(`/api/library/${type}/${local}`,{method:'DELETE'});return loadEntityLibrary(type)}
      if(b.hasAttribute('data-detail'))return type==='performers'?performerProfile(id,local):type==='studios'?studioProfile(id,local):localDetail(type,local);
      if(b.hasAttribute('data-remote-detail'))return type==='performers'?performerProfile(id,null):type==='studios'?studioProfile(id,null):remoteDetail(type,id);
    }catch(err){notify(err.message,'error');b.disabled=false}
  }
}

async function monitorAllEntity(type,id,localId,button){
  button.disabled=true;button.textContent='Monitoring All…';
  try{let r=localId?await api(`/api/library/${type}/${localId}/monitor`,patch({monitored:true})):await api(`/api/library/${type}/${encodeURIComponent(id)}`,post({monitored:true}));button.textContent='Monitor All ✓';notify(`Monitor All started${r.job_id?` (job ${r.job_id})`:''}. ScarletX is searching every eligible studio scene and will download the best matches.`,'ok');return r}catch(e){button.disabled=false;button.textContent='Monitor All';throw e}
}
function sceneProfileList(rows){return sceneTable(rows,false)}
function bindProfileSceneLinks(root){bindSceneTableActions(root,false)}

function numericPart(v){let m=String(v??'').replace(/,/g,'.').match(/-?\d+(?:\.\d+)?/);return m?Number(m[0]):null}
function trimNum(v,d=0){return Number(v).toFixed(d).replace(/\.0+$/,'')}
function usHeight(v){if(v===null||v===undefined||String(v).trim()==='')return null;let raw=String(v).trim().toLowerCase(),cm=null,inches=null;let feet=raw.match(/(\d+)\s*['′]\s*(\d+(?:\.\d+)?)?/);if(feet){inches=Number(feet[1])*12+Number(feet[2]||0);cm=inches*2.54}else{let n=numericPart(raw);if(n===null)return v;if(/\bcm\b/.test(raw)||n>100)cm=n;else if(/\bm\b/.test(raw)&&n<3)cm=n*100;else if(/in|inch|"|″/.test(raw)||n>=48)inches=n;else cm=n;if(inches===null)inches=cm/2.54;if(cm===null)cm=inches*2.54}let ft=Math.floor(inches/12),inch=Math.round(inches-ft*12);if(inch===12){ft++;inch=0}return `${ft}'${inch}" (${Math.round(cm)} cm)`}
function usWeight(v){if(v===null||v===undefined||String(v).trim()==='')return null;let raw=String(v).trim().toLowerCase(),n=numericPart(raw);if(n===null)return v;let kg,lb;if(/lb|pound/.test(raw)){lb=n;kg=lb/2.2046226218}else{kg=n;lb=kg*2.2046226218}return `${Math.round(lb)} lb (${trimNum(kg,1)} kg)`}
function usLength(v){if(v===null||v===undefined||String(v).trim()==='')return null;let raw=String(v).trim().toLowerCase(),n=numericPart(raw);if(n===null)return v;let inch,cm;if(/cm/.test(raw)||n>50){cm=n;inch=cm/2.54}else{inch=n;cm=inch*2.54}return `${trimNum(inch,1)} in (${Math.round(cm)} cm)`}
function usMeasurements(v){if(v===null||v===undefined||String(v).trim()==='')return null;let raw=String(v).trim(),nums=[...raw.matchAll(/\d+(?:\.\d+)?/g)].map(m=>Number(m[0]));if(nums.length<3)return raw;let metric=nums.some(n=>n>55),us=metric?nums.map(n=>n/2.54):nums,cm=metric?nums:nums.map(n=>n*2.54);return `${us.slice(0,3).map(n=>trimNum(n,1)).join('-')} in (${cm.slice(0,3).map(n=>Math.round(n)).join('-')} cm)`}
function performerFacts(x,monitored=null){
  let facts=[];let add=(label,value)=>{if(value!==null&&value!==undefined&&String(value).trim()!=='')facts.push(`<div class="profile-fact"><b>${esc(label)}</b><span>${esc(value)}</span></div>`)};
  if(monitored!==null)add('Monitored',monitored?'Yes':'No');
  add('Status',x.status||((x.deathday)?'Deceased':(x.career_end_year?'Retired':(x.career_start_year?'Active':'Unknown'))));
  add('Age',x.age);add('Born',x.birthday?fmtDate(x.birthday):null);
  add('Measurements',usMeasurements(x.measurements));add('Cup size',x.cup_size);
  add('Breasts',x.fake_boobs===true?'Enhanced / Fake':x.fake_boobs===false?'Natural':null);
  add('Waist',usLength(x.waist));add('Hips',usLength(x.hips));add('Height',usHeight(x.height));add('Weight',usWeight(x.weight));
  add('Ethnicity',x.ethnicity);add('Nationality',x.nationality);add('Birthplace',x.birthplace);
  add('Hair',x.hair_color);add('Eyes',x.eye_color);add('Astrology',x.astrology);
  add('Career',x.career_start_year?`${x.career_start_year} – ${x.career_end_year||'Present'}`:null);
  add('Tattoos',x.tattoos);add('Piercings',x.piercings);
  add('Aliases',(x.aliases||[]).join(', '));
  return facts.join('');
}
