async function scenePage(id,localId=null){
  let local=null,remote=null;
  try{
    if(localId){try{local=await api(`/api/library/scenes/${encodeURIComponent(localId)}/detail`)}catch(_){local=null}}
    try{remote=await api(`/api/metadata/scenes/${encodeURIComponent(id)}`)}catch(_){remote=null}
    let x={...(local||{}),...(remote||{})},files=local?.files||[];
    let mediaRows=local?.files||[];
    let firstMedia=mediaRows[0],hero=firstMedia?`/api/media-files/${firstMedia.id}/screengrab`:((x.back_image_url||x.image_url||x.poster_url)?`/api/artwork/scenes/${encodeURIComponent(id)}`:'');
    let studio=x.studio?.name||local?.studio||'—',studioId=x.studio?.id||local?.studio_id;
    let perf=x.performers||local?.performers||[];
    $('#app').innerHTML=pageHead(x.title||'Scene','',`<button class="btn" id="backScenes">← Scenes</button>${local?.monitored?'':`<button class="btn primary" id="monitorScenePage">Monitor</button>`}${firstMedia?`<button class="btn primary" id="playScenePage">Play</button>`:''}`)+`<div class="profile-shell"><div class="profile-image">${hero?`<img src="${esc(hero)}" alt="${esc(x.title||'Scene')}" loading="eager" onerror="this.remove()">`:'No screengrab available.'}</div><div><div class="profile-facts"><div class="profile-fact"><b>Studio</b><span>${studioId?`<button class="credit-link" data-scene-studio="${esc(studioId)}">${esc(studio)}</button>`:esc(studio)}</span></div><div class="profile-fact"><b>Release</b><span>${fmtDate(x.release_date)}</span></div><div class="profile-fact"><b>Runtime</b><span>${durationText(x.duration)}</span></div><div class="profile-fact"><b>Status</b><span>${firstMedia?'Downloaded':local?.monitored?'Monitored':'Available'}</span></div><div class="profile-fact"><b>Files</b><span>${mediaRows.length||files.length||0}</span></div></div>${x.description?`<div class="profile-section"><h2>Description</h2><div class="profile-bio">${esc(x.description)}</div></div>`:''}<div class="profile-section"><h2>Performers</h2><div class="profile-links">${perf.length?perf.map(p=>`<button class="credit-link" data-scene-performer="${esc(p.id)}">${esc(p.name)}</button>`).join(' '):'—'}</div></div>${x.tags?.length?`<div class="profile-section"><h2>Tags</h2><div class="profile-links">${x.tags.map(t=>`<span class="state">${esc(t.name||t)}</span>`).join(' ')}</div></div>`:''}</div></div>`;
    $('#backScenes').onclick=()=>{view='scenes';entityMode.scenes='library';renderEntities('scenes')};if($('#playScenePage'))$('#playScenePage').onclick=()=>playMedia(firstMedia.id);if($('#monitorScenePage'))$('#monitorScenePage').onclick=async e=>{e.currentTarget.disabled=true;e.currentTarget.textContent='Starting…';try{await api(localId?`/api/library/scenes/${localId}/monitor`:`/api/metadata/scenes/${encodeURIComponent(id)}/monitor`,post());notify('Monitoring started. ScarletX is searching and downloading in the background.','ok');setTimeout(()=>scenePage(id,localId),800)}catch(err){notify(err.message,'error');e.currentTarget.disabled=false}};
    $$('[data-scene-performer]').forEach(b=>b.onclick=()=>performerProfile(b.dataset.scenePerformer,null));$$('[data-scene-studio]').forEach(b=>b.onclick=()=>studioProfile(b.dataset.sceneStudio,null));
  }catch(e){notify(e.message,'error')}
}

async function remoteDetail(type,id){if(type==='studios')return studioProfile(id,null);try{let x=await api(`/api/metadata/${type}/${encodeURIComponent(id)}`);if(type==='performers')return modal(x.name||'Performer',performerDetailBody(x,id));modal(x.title||x.name||'Details',`<div class="formgrid"><div class="span2"><p>${esc(x.description||x.bio||'No description available.')}</p></div>${x.release_date?`<div><b>Release</b><div class="muted">${fmtDate(x.release_date)}</div></div>`:''}</div>`)}catch(e){notify(e.message,'error')}}
