  $('#searchWanted').onclick=async()=>{let b=$('#searchWanted');b.disabled=true;b.textContent='Searching…';try{let r=await api('/api/wanted/search?limit=25',post());notify(`Checked ${r.checked}; queued ${r.queued}.`,'ok');wanted()}catch(e){notify(e.message,'error')}finally{b.disabled=false}};
  try{let rows=await api('/api/wanted/missing?limit=500');$('#wantedBody').innerHTML=rows.length?`<div class="tablewrap"><table class="table"><thead><tr><th>Scene</th><th>Release</th><th>Status</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.title)}</b></td><td>${fmtDate(x.release_date)}</td><td><span class="state warn">Missing</span></td></tr>`).join('')}</tbody></table></div>`:empty('Nothing is wanted. All monitored scenes have files.') }catch(e){notify(e.message,'error')}
