function activityQueueHtml(rows){
  return rows.length?`<div class="tablewrap" style="border:0;border-radius:0"><table class="table"><thead><tr><th>Scene</th><th>Status</th><th>Progress</th><th>Speed / ETA</th><th></th></tr></thead><tbody>${rows.map(x=>{let pct=x.progress==null?'—':`${Number(x.progress).toFixed(1)}%`,speed=x.speed_bps?`${bytes(x.speed_bps)}/s`:'—',eta=x.eta_seconds!=null?`${Math.floor(x.eta_seconds/60)}m ${x.eta_seconds%60}s`:'—',state=x.client_status||x.status,done=x.downloaded_bytes!=null?bytes(x.downloaded_bytes):'—',total=x.total_bytes?bytes(x.total_bytes):'—',buttons=['queued','downloading'].includes(state)?`<button class="btn small" data-native-act="pause" data-job="${esc(x.external_id)}">Pause</button><button class="btn small danger" data-native-act="cancel" data-job="${esc(x.external_id)}">Cancel</button>`:state==='postprocessing'?`<button class="btn small danger" data-native-act="cancel" data-job="${esc(x.external_id)}">Cancel</button>`:state==='paused'?`<button class="btn small primary" data-native-act="resume" data-job="${esc(x.external_id)}">Resume</button>`:'';return `<tr data-live-job="${esc(x.external_id)}"><td><b class="live-title">${esc(x.scene_title||x.release_title||'Download')}</b></td><td><span class="state warn live-status">${esc(state)}</span><small class="live-stage">${state==='postprocessing'?esc(x.postprocess_note||'Preparing media…'):''}</small></td><td><b class="live-pct">${pct}</b><small class="live-bytes">${done} / ${total}</small><div class="mini-progress" ${x.progress==null?'style="display:none"':''}><i class="live-bar" style="width:${Math.min(100,Number(x.progress||0))}%"></i></div></td><td><b class="live-speed">${speed}</b><small class="live-eta">${eta!=='—'?`ETA ${eta}`:''}</small><small class="live-provider">${x.provider?`Best: ${esc(x.provider)}${x.active_connections?` • ${x.active_connections}/${x.connection_cap||x.active_connections} conns`:''}`:(x.active_connections?`${x.active_connections}/${x.connection_cap||x.active_connections} conns`:'')}</small></td><td><div class="actions live-actions">${buttons}</div></td></tr>`}).join('')}</tbody></table></div>`:empty('No active downloads.');
}

function applyLiveQueue(q){
  let rows=q.tracked||[],el=$('#activityQueue');
  if(el){
    let current=[...el.querySelectorAll('[data-live-job]')],currentIds=current.map(r=>r.dataset.liveJob),nextIds=rows.map(x=>String(x.external_id||''));
    if(!current.length||currentIds.join('|')!==nextIds.join('|')) el.innerHTML=activityQueueHtml(rows);
    else rows.forEach((x,i)=>{let r=current[i],pct=x.progress==null?null:Number(x.progress),state=x.client_status||x.status,speed=x.speed_bps?`${bytes(x.speed_bps)}/s`:'—',eta=x.eta_seconds!=null?`${Math.floor(x.eta_seconds/60)}m ${x.eta_seconds%60}s`:'',buttons=['queued','downloading'].includes(state)?`<button class="btn small" data-native-act="pause" data-job="${esc(x.external_id)}">Pause</button><button class="btn small danger" data-native-act="cancel" data-job="${esc(x.external_id)}">Cancel</button>`:state==='postprocessing'?`<button class="btn small danger" data-native-act="cancel" data-job="${esc(x.external_id)}">Cancel</button>`:state==='paused'?`<button class="btn small primary" data-native-act="resume" data-job="${esc(x.external_id)}">Resume</button>`:'';r.querySelector('.live-title').textContent=x.scene_title||x.release_title||'Download';r.querySelector('.live-status').textContent=state;let ls=r.querySelector('.live-stage');if(ls)ls.textContent=state==='postprocessing'?(x.postprocess_note||'Preparing media…'):'';r.querySelector('.live-pct').textContent=pct==null?'—':`${pct.toFixed(1)}%`;r.querySelector('.live-bytes').textContent=`${x.downloaded_bytes!=null?bytes(x.downloaded_bytes):'—'} / ${x.total_bytes?bytes(x.total_bytes):'—'}`;let pb=r.querySelector('.mini-progress');pb.style.display=pct==null?'none':'';r.querySelector('.live-bar').style.width=`${Math.min(100,pct||0)}%`;r.querySelector('.live-speed').textContent=speed;r.querySelector('.live-eta').textContent=eta?`ETA ${eta}`:'';let lp=r.querySelector('.live-provider');if(lp)lp.textContent=x.provider?`Best: ${x.provider}${x.active_connections?` • ${x.active_connections}/${x.connection_cap||x.active_connections} conns`:''}`:(x.active_connections?`${x.active_connections}/${x.connection_cap||x.active_connections} conns`:'');r.querySelector('.live-actions').innerHTML=buttons});
  }
  $('#queueBadge').textContent=rows.length;
}
async function resyncLiveQueue(){
  if(liveQueueBusy)return;
  liveQueueBusy=true;
  try{liveQueueSnapshot=await api('/api/activity/queue');applyLiveQueue(liveQueueSnapshot)}catch(_){}finally{liveQueueBusy=false}
}
function mergeLiveQueueJob(job){
  let rows=[...(liveQueueSnapshot.tracked||[])],key=String(job.external_id||job.id||''),i=rows.findIndex(x=>String(x.external_id||x.id||'')===key);
  if(i>=0)rows[i]={...rows[i],...job};else rows.push(job);
  liveQueueSnapshot={...liveQueueSnapshot,tracked:rows};applyLiveQueue(liveQueueSnapshot);
}
async function refreshLiveQueueFallback(){
  await resyncLiveQueue();
  if(!liveQueueTimer)liveQueueTimer=setTimeout(()=>{liveQueueTimer=null;refreshLiveQueueFallback()},15000);
}
window.addEventListener('scarletx:queue-event',e=>{
  let detail=e.detail||{},kind=detail.kind,payload=detail.payload||{};
  if(kind==='snapshot'){liveQueueSnapshot=payload;applyLiveQueue(liveQueueSnapshot);return}
  if((kind==='progress'||kind==='transition')&&payload.job){mergeLiveQueueJob(payload.job);return}
  if(kind==='resync'){
    if(payload.snapshot){liveQueueSnapshot=payload.snapshot;applyLiveQueue(liveQueueSnapshot)}else resyncLiveQueue();
  }
});
window.addEventListener('scarletx:queue-stream-fallback',()=>{
  if(!liveQueueTimer)liveQueueTimer=setTimeout(()=>{liveQueueTimer=null;refreshLiveQueueFallback()},15000);
});
window.addEventListener('scarletx:queue-stream-healthy',()=>stopLiveQueue());

async function activity(){
  $('#app').innerHTML=pageHead('Activity','',`<button class="btn" id="processNow">Process Completed</button>`)+`<div class="panel"><div class="panel-head"><h2>Active Queue</h2><span class="client-chip" id="liveQueueState">LIVE</span></div><div id="activityQueue"></div></div><div style="height:14px"></div><div class="panel"><div class="panel-head"><h2>Completed</h2></div><div id="activityCompleted"></div></div><div style="height:14px"></div><div class="panel"><div class="panel-head"><h2>Failed</h2><button class="btn small danger" id="clearFailed">Clear Failed</button></div><div id="activityFailed"></div></div><div style="height:14px"></div><div class="panel"><div class="panel-head"><h2>History</h2></div><div id="activityHistory"></div></div>`;
  $('#processNow').onclick=async()=>{try{let r=await api('/api/downloads/process',post());notify(`Checked ${r.checked}; imported ${r.imported}; failed ${r.failed}.`,'ok');activity()}catch(e){notify(e.message,'error')}};
  $('#clearFailed').onclick=async e=>{if(!confirm('Clear all failed downloads and their partial files?'))return;e.currentTarget.disabled=true;try{let r=await api('/api/downloads/failed',{method:'DELETE'});notify(`Cleared ${r.cleared} failed download${r.cleared===1?'':'s'}.`,'ok');activity()}catch(err){notify(err.message,'error');e.currentTarget.disabled=false}};
  $('#activityQueue').onclick=async e=>{let b=e.target.closest('[data-native-act]');if(!b)return;b.disabled=true;try{await api(`/api/downloads/native/${encodeURIComponent(b.dataset.job)}/${b.dataset.nativeAct}`,post());await resyncLiveQueue()}catch(err){notify(err.message,'error');b.disabled=false}};
  try{
    let [q,c,f,h]=await Promise.all([api('/api/activity/queue'),api('/api/downloads/completed?limit=100'),api('/api/downloads/failed'),api('/api/history?limit=200')]),rows=q.tracked||[],completed=c.scarletx||[],failed=f.scarletx||[];
    liveQueueSnapshot=q;applyLiveQueue(q);
    $('#activityCompleted').innerHTML=completed.length?`<div class="tablewrap" style="border:0;border-radius:0"><table class="table"><thead><tr><th>Scene</th><th>Size</th><th>Completed</th><th>Import</th><th>Post-processing</th><th></th></tr></thead><tbody>${completed.map(x=>`<tr><td><b>${esc(x.scene_title||x.release_title||x.title||'Download')}</b></td><td>${bytes(x.total_bytes||x.downloaded_bytes||0)}</td><td>${fmtDate(x.completed_at)}</td><td><span class="state ${x.imported_at?'good':'warn'}">${x.imported_at?'Imported':'Awaiting import'}</span></td><td><small>${esc(x.postprocess_note||'Download complete')}</small></td><td>${x.imported_at?'':`<button class="btn small primary" data-reprocess-completed data-job="${esc(x.id)}">Reprocess</button>`}</td></tr>`).join('')}</tbody></table></div>`:empty('No completed downloads yet.');
    $('#activityCompleted').onclick=async e=>{let b=e.target.closest('[data-reprocess-completed]');if(!b)return;b.disabled=true;b.textContent='Reprocessing…';try{await api(`/api/downloads/native/${encodeURIComponent(b.dataset.job)}/reprocess`,post());notify('Completed payload reprocessed. Import will run automatically.','ok');activity()}catch(err){notify(err.message,'error');b.disabled=false;b.textContent='Reprocess'}};
    $('#activityFailed').innerHTML=failed.length?`<div class="tablewrap" style="border:0;border-radius:0"><table class="table"><thead><tr><th>Scene</th><th>Failure</th><th>Partial</th><th></th></tr></thead><tbody>${failed.map(x=>`<tr><td><b>${esc(x.title||'Download')}</b></td><td><span class="state bad">Failed</span><small>${esc(x.error||'Download failed')}</small></td><td>${bytes(x.downloaded_bytes||0)} / ${x.total_bytes?bytes(x.total_bytes):'—'}</td><td><div class="actions"><button class="btn small primary" data-failed-retry data-job="${esc(x.id)}">Retry</button><button class="btn small" data-native-password data-job="${esc(x.id)}">Archive Password</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('No failed downloads.');
    $('#activityFailed').onclick=async e=>{let pw=e.target.closest('[data-native-password]');if(pw){let password=prompt('Archive password for this download:','');if(password===null)return;try{await api(`/api/downloads/native/${encodeURIComponent(pw.dataset.job)}/password`,post({password}));notify('Archive password saved.','ok')}catch(err){notify(err.message,'error')}return}let b=e.target.closest('[data-failed-retry]');if(!b)return;b.disabled=true;try{await api(`/api/downloads/native/${encodeURIComponent(b.dataset.job)}/resume`,post());notify('Failed download moved back to the queue.','ok');activity()}catch(err){notify(err.message,'error');b.disabled=false}};
    $('#activityHistory').innerHTML=h.length?`<div class="tablewrap" style="border:0;border-radius:0"><table class="table"><thead><tr><th>Event</th><th>Message</th><th>Date</th></tr></thead><tbody>${h.map(x=>`<tr><td>${esc(x.event_type)}</td><td>${esc(x.message)}</td><td>${fmtDate(x.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No history yet.');
  }catch(e){notify(e.message,'error')}
}



async function calendar(){
  $('#app').innerHTML=pageHead('Calendar','Upcoming release dates for monitored scenes.')+`<div id="calendarBody"></div>`;try{let rows=await api('/api/calendar');$('#calendarBody').innerHTML=rows.length?`<div class="tablewrap"><table class="table"><thead><tr><th>Date</th><th>Scene</th><th>Monitored</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${fmtDate(x.date)}</td><td><b>${esc(x.title)}</b></td><td><span class="state ${x.monitored?'good':'warn'}">${x.monitored?'Yes':'No'}</span></td></tr>`).join('')}</tbody></table></div>`:empty('No upcoming monitored releases in the next 90 days.')}catch(e){notify(e.message,'error')}
}

let settingsTab='general';
async function settings(){
  try{settingsCache=await api('/api/settings')}catch(e){return notify(e.message,'error')}
  let tabs=[['general','General'],['metadata','TPDB'],['indexers','Indexers'],['downloads','Download Client'],['media','Media Management'],['automation','Automation'],['backups','Backups'],['security','Security'],['system','System']];
  $('#app').innerHTML=pageHead('Settings','Configure ScarletX and its integrations.')+`<div class="settings-layout"><div class="settings-nav">${tabs.map(t=>`<button data-tab="${t[0]}" class="${settingsTab===t[0]?'active':''}">${t[1]}</button>`).join('')}</div><div id="settingsBody"></div></div>`;
  $$('.settings-nav button').forEach(b=>b.onclick=()=>{settingsTab=b.dataset.tab;settings()});renderSettingsTab()
}
function val(id){return $(id).value.trim()}
async function renderSettingsTab(){let s=settingsCache,el=$('#settingsBody');
 if(settingsTab==='general'){el.innerHTML=`<div class="settings-panel"><h2>General</h2><p>ScarletX application identity and logging.</p><div class="formgrid"><div class="field"><label>Application name</label><input class="input" id="appName" value="${esc(s.general.app_name)}"></div><div class="field"><label>Log level</label><select id="logLevel">${['DEBUG','INFO','WARNING','ERROR'].map(x=>`<option ${s.general.log_level===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="divider"></div><button class="btn primary" id="saveGeneral">Save</button></div>`;$('#saveGeneral').onclick=()=>saveSetting('/api/settings/general',{app_name:val('#appName'),log_level:val('#logLevel')});return}
 if(settingsTab==='metadata'){el.innerHTML=`<div class="settings-panel"><h2>ThePornDB</h2><p>Primary metadata source for scenes, performers, and studios.</p><div class="formgrid"><div class="field span2"><label>API key</label><input class="input" id="tpdbKey" type="password" placeholder="${s.theporndb.configured?'Configured — leave blank to keep current':'Enter TPDB API key'}"><span class="hint">This local development preview includes a baked TPDB development key. Saving another key here overrides it locally.</span></div><div class="field span2"><label>API URL</label><input class="input" id="tpdbUrl" value="${esc(s.theporndb.base_url)}"></div></div><div class="divider"></div><button class="btn primary" id="saveTPDB">Save TPDB</button></div>`;$('#saveTPDB').onclick=()=>saveSetting('/api/settings/theporndb',{api_key:val('#tpdbKey')||null,base_url:val('#tpdbUrl')});return}
 if(settingsTab==='indexers')return renderIndexers();
 if(settingsTab==='downloads')return renderDownloadSettings();
 if(settingsTab==='media')return renderMediaSettings();
 if(settingsTab==='automation'){let a=s.automation,r=s.rss;el.innerHTML=`<div class="settings-panel"><h2>Automation</h2><p>Automatic scene searches and RSS matching.</p><div class="formgrid"><div class="field"><label>Automatic search</label><select id="autoEnabled"><option value="true" ${a.enabled?'selected':''}>Enabled</option><option value="false" ${!a.enabled?'selected':''}>Disabled</option></select></div><div class="field"><label>Interval minutes</label><input class="input" id="autoInterval" type="number" min="5" value="${a.interval_minutes}"></div><div class="field"><label>Batch size</label><input class="input" id="autoBatch" type="number" min="1" value="${a.batch_size}"></div></div><div class="divider"></div><h2>RSS</h2><div class="formgrid"><div class="field"><label>RSS sync</label><select id="rssEnabled"><option value="true" ${r.enabled?'selected':''}>Enabled</option><option value="false" ${!r.enabled?'selected':''}>Disabled</option></select></div><div class="field"><label>Interval minutes</label><input class="input" id="rssInterval" type="number" min="5" value="${r.interval_minutes}"></div><div class="field"><label>Releases per indexer</label><input class="input" id="rssMax" type="number" min="10" value="${r.max_releases_per_indexer}"></div><div class="field"><label>Max grabs per cycle</label><input class="input" id="rssGrab" type="number" min="1" value="${r.max_grabs_per_cycle}"></div></div><div class="divider"></div><button class="btn primary" id="saveAuto">Save Automation</button></div>`;$('#saveAuto').onclick=async()=>{await api('/api/settings/automation',patch({enabled:val('#autoEnabled')==='true',interval_minutes:Number(val('#autoInterval')),batch_size:Number(val('#autoBatch'))}));await api('/api/settings/rss',patch({enabled:val('#rssEnabled')==='true',interval_minutes:Number(val('#rssInterval')),max_releases_per_indexer:Number(val('#rssMax')),max_grabs_per_cycle:Number(val('#rssGrab'))}));notify('Automation settings saved.','ok');settings()};return}
 if(settingsTab==='backups'){let b=s.backups;el.innerHTML=`<div class="settings-panel"><h2>Backups</h2><p>Local SQLite database backup rotation.</p><div class="formgrid"><div class="field"><label>Enabled</label><select id="backupEnabled"><option value="true" ${b.enabled?'selected':''}>Enabled</option><option value="false" ${!b.enabled?'selected':''}>Disabled</option></select></div><div class="field"><label>Directory</label><input class="input" id="backupDir" value="${esc(b.directory)}"></div><div class="field"><label>Interval hours</label><input class="input" id="backupHours" type="number" value="${b.interval_hours}"></div><div class="field"><label>Keep</label><input class="input" id="backupKeep" type="number" value="${b.keep}"></div></div><div class="divider"></div><div class="actions"><button class="btn primary" id="saveBackup">Save</button><button class="btn" id="backupNow">Backup Now</button></div></div>`;$('#saveBackup').onclick=()=>saveSetting('/api/settings/backups',{enabled:val('#backupEnabled')==='true',directory:val('#backupDir'),interval_hours:Number(val('#backupHours')),keep:Number(val('#backupKeep'))});$('#backupNow').onclick=async()=>{try{let r=await api('/api/backups',post());notify(`Backup created: ${r.path}`,'ok')}catch(e){notify(e.message,'error')}};return}
 if(settingsTab==='security'){let z=s.security;el.innerHTML=`<div class="settings-panel"><h2>API Security</h2><p>Optional API-key protection for ScarletX API routes.</p><div class="formgrid"><div class="field"><label>API key protection</label><select id="apiEnabled"><option value="true" ${z.api_key_enabled?'selected':''}>Enabled</option><option value="false" ${!z.api_key_enabled?'selected':''}>Disabled</option></select></div><div class="field"><label>API key</label><input class="input" id="apiKey" type="password" placeholder="${z.api_key_configured?'Configured — blank keeps current':'Enter a key'}"></div></div><div class="divider"></div><button class="btn primary" id="saveSecurity">Save</button></div>`;$('#saveSecurity').onclick=()=>saveSetting('/api/settings/security',{api_key_enabled:val('#apiEnabled')==='true',api_key:val('#apiKey')||null});return}
 if(settingsTab==='system'){el.innerHTML=`<div class="settings-panel"><h2>System</h2><p>Runtime health and storage.</p><div id="systemSettings">Loading…</div></div>`;let [st,h,d]=await Promise.all([api('/api/system/status'),api('/api/system/health'),api('/api/system/diskspace')]);$('#systemSettings').innerHTML=`<div class="formgrid"><div><b>Version</b><div class="muted">${esc(st.version)}</div></div><div><b>Database</b><div class="muted">${esc(st.database)}</div></div><div><b>Health</b><div class="state ${h.status==='ok'?'good':h.status==='warning'?'warn':'bad'}">${esc(h.status)}</div></div><div><b>Tracked media files</b><div class="muted">${st.media_files}</div></div></div><div class="divider"></div>${d.length?`<div class="tablewrap"><table class="table"><thead><tr><th>Scene Root</th><th>Path</th><th>Free</th></tr></thead><tbody>${d.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.path)}</td><td>${x.exists?bytes(x.free_bytes):'Missing'}</td></tr>`).join('')}</tbody></table></div>`:empty('No scene root folder configured.')}`;return}
}
async function saveSetting(path,body){try{await api(path,patch(body));notify('Settings saved.','ok');settings()}catch(e){notify(e.message,'error')}}
async function renderIndexers(){let el=$('#settingsBody'),rows=settingsCache.newznab_indexers;el.innerHTML=`<div class="settings-panel"><h2>Newznab Indexers</h2><p>Usenet indexers used for adult scene search and RSS.</p><div id="indexers">${(rows.length?rows:[{}]).map(indexerRow).join('')}</div><div class="actions"><button class="btn" id="addIndexer">＋ Add Indexer</button><button class="btn primary" id="saveIndexers">Save Indexers</button></div></div>`;$('#addIndexer').onclick=()=>$('#indexers').insertAdjacentHTML('beforeend',indexerRow({}));$('#indexers').onclick=e=>{let b=e.target.closest('[data-remove-indexer]');if(b)b.closest('.indexer').remove()};$('#saveIndexers').onclick=async()=>{let indexers=$$('.indexer').map(r=>({name:r.querySelector('[data-k=name]').value.trim(),url:r.querySelector('[data-k=url]').value.trim(),api_key:r.querySelector('[data-k=key]').value.trim()||null,adult_categories:r.querySelector('[data-k=cats]').value.split(',').map(x=>Number(x.trim())).filter(Boolean),enabled:r.querySelector('[data-k=enabled]').value==='true',rss_enabled:r.querySelector('[data-k=rss]').value==='true',priority:Number(r.querySelector('[data-k=priority]').value||25)})).filter(x=>x.name&&x.url);try{await api('/api/settings/newznab',patch({indexers}));notify('Indexers saved.','ok');settings()}catch(e){notify(e.message,'error')}}}
function indexerRow(x={}){return `<div class="indexer"><div class="indexer-grid"><div class="field"><label>Name</label><input class="input" data-k="name" value="${esc(x.name||'')}"></div><div class="field"><label>API URL</label><input class="input" data-k="url" value="${esc(x.url||'')}"></div><div class="field"><label>API key</label><input class="input" type="password" data-k="key" placeholder="${x.api_key_configured?'Configured — blank keeps current':''}"></div><div class="field"><label>Priority</label><input class="input" type="number" data-k="priority" value="${x.priority||25}"></div><div class="field"><label>Adult categories</label><input class="input" data-k="cats" value="${esc((x.adult_categories||[6000,6010,6020,6040]).join(','))}"></div><div class="field"><label>Enabled</label><select data-k="enabled"><option value="true" ${x.enabled!==false?'selected':''}>Yes</option><option value="false" ${x.enabled===false?'selected':''}>No</option></select></div><div class="field"><label>RSS</label><select data-k="rss"><option value="true" ${x.rss_enabled!==false?'selected':''}>Yes</option><option value="false" ${x.rss_enabled===false?'selected':''}>No</option></select></div><div class="field"><label>&nbsp;</label><button class="btn danger" data-remove-indexer>Remove</button></div></div></div>`}
function providerRow(x={}){return `<div class="provider" data-provider><div class="provider-grid"><div class="field"><label>Name</label><input class="input" data-p="name" value="${esc(x.name||'')}"></div><div class="field"><label>NNTP Host</label><input class="input" data-p="host" value="${esc(x.host||'')}"></div><div class="field"><label>Port</label><input class="input" type="number" data-p="port" value="${x.port||563}"></div><div class="field"><label>Username</label><input class="input" data-p="username" value="${esc(x.username||'')}"></div><div class="field"><label>Password</label><input class="input" type="password" data-p="password" placeholder="${x.password_configured?'Configured — blank keeps current':''}"></div><div class="field"><label>SSL/TLS</label><input class="input" value="Required" disabled><span class="hint">Plaintext NNTP is not supported.</span></div><div class="field"><label>Connections</label><input class="input" type="number" min="1" max="150" data-p="connections" value="${x.connections||8}"></div></div><div class="actions" style="margin-top:8px"><div class="field" style="width:105px"><label>Priority</label><input class="input" type="number" min="1" max="50" data-p="priority" value="${x.priority||25}"></div><div class="field" style="width:105px"><label>Enabled</label><select data-p="enabled"><option value="true" ${x.enabled!==false?'selected':''}>Yes</option><option value="false" ${x.enabled===false?'selected':''}>No</option></select></div><button class="btn small" data-test-provider>Test</button><button class="btn small danger" data-remove-provider>Remove</button></div></div>`}
function collectProviders(){return $$('[data-provider]').map(r=>({name:r.querySelector('[data-p=name]').value.trim(),host:r.querySelector('[data-p=host]').value.trim(),port:Number(r.querySelector('[data-p=port]').value||563),username:r.querySelector('[data-p=username]').value.trim(),password:r.querySelector('[data-p=password]').value.trim()||null,use_ssl:true,connections:Number(r.querySelector('[data-p=connections]').value||8),enabled:r.querySelector('[data-p=enabled]').value==='true',priority:Number(r.querySelector('[data-p=priority]').value||25)})).filter(x=>x.name&&x.host)}
async function renderDownloadSettings(){let el=$('#settingsBody'),n=settingsCache.native_usenet,tools=n.tools||{};el.innerHTML=`<div class="settings-panel"><h2>ScarletX Built-In Usenet</h2><p>ScarletX downloads NZBs directly over encrypted NNTP/TLS. Plaintext NNTP is disabled.</p><div class="formgrid"><div class="field"><label>Built-in downloader</label><select id="nativeEnabled"><option value="true" ${n.enabled?'selected':''}>Enabled</option><option value="false" ${!n.enabled?'selected':''}>Disabled</option></select></div><div class="field"><label>Adaptive connection cap</label><input class="input" id="nativeConnections" type="number" min="1" max="200" value="${n.max_connections}"><span class="hint">ScarletX starts smaller and automatically ramps toward this cap while measured throughput keeps improving. Provider values remain hard maximums.</span></div><div class="field span2"><label>Incomplete directory</label><input class="input" id="nativeIncomplete" value="${esc(n.incomplete_dir)}"></div><div class="field span2"><label>Completed directory</label><input class="input" id="nativeComplete" value="${esc(n.complete_dir)}"></div><div class="field"><label>Extra transient retries</label><input class="input" id="nativeRetries" type="number" min="0" max="3" value="${Math.min(3,n.max_retries)}"><span class="hint">Total extra attempts across all providers. Missing articles immediately rotate servers.</span></div><div class="field"><div class="speed-limit-control"><div class="speed-limit-head"><label>Download speed limit</label><output class="speed-limit-value" id="nativeSpeedValue">${Number(n.speed_limit_mb_s||0)>0?`${Number(n.speed_limit_mb_s).toFixed(Number(n.speed_limit_mb_s)%1?1:0)} MB/s`:'Unlimited'}</output></div><input class="speed-slider" id="nativeSpeed" type="range" min="0" max="250" step="0.5" value="${Math.min(250,Number(n.speed_limit_mb_s||0))}" aria-label="Download speed limit in megabytes per second"><div class="speed-scale"><span>Unlimited</span><span>50</span><span>100</span><span>150</span><span>200</span><span>250 MB/s</span></div><span class="hint">Applies to ScarletX's built-in downloader. Move fully left for no speed limit.</span></div></div><div class="field"><label>PAR2 repair</label><select id="nativeRepair"><option value="true" ${n.repair_enabled?'selected':''}>Enabled</option><option value="false" ${!n.repair_enabled?'selected':''}>Disabled</option></select></div><div class="field"><label>Unpack archives</label><select id="nativeUnpack"><option value="true" ${n.unpack_enabled?'selected':''}>Enabled</option><option value="false" ${!n.unpack_enabled?'selected':''}>Disabled</option></select></div></div><div class="divider"></div><h2>Usenet Providers</h2><p>Astraweb and Newshosting are preconfigured for this private development build. ScarletX uses TLS-only, keeps provider sessions warm, and dynamically stripes scene segments across the fastest healthy servers.</p><div id="providers">${(n.providers||[]).map(providerRow).join('')}</div><div class="actions"><button class="btn" id="addProvider">＋ Add Provider</button><button class="btn primary" id="saveNative">Save Download Settings</button></div><div class="divider"></div><h2>Post-processing tools</h2><div class="tool-grid"><span class="tool-pill ${tools.sabctools?'good':'warn'}">SIMD yEnc ${tools.sabctools?'Ready':'Fallback'}</span><span class="tool-pill ${tools.par2?'good':'warn'}">PAR2 ${tools.par2?'Ready':'Not installed'}</span><span class="tool-pill ${tools.unrar?'good':'warn'}">unrar ${tools.unrar?'Ready':'Not installed'}</span><span class="tool-pill ${tools['7z']?'good':'warn'}">7z ${tools['7z']?'Ready':'Not installed'}</span></div><p class="hint">Direct video NZBs work without these tools. RAR/PAR posts need PAR2 plus unrar or 7z for automatic repair and extraction.</p></div>`;
 const speedSlider=$('#nativeSpeed'),speedValue=$('#nativeSpeedValue');
 const updateSpeedLabel=()=>{let v=Number(speedSlider.value||0);speedValue.textContent=v>0?`${v.toFixed(v%1?1:0)} MB/s`:'Unlimited'};
 speedSlider.oninput=updateSpeedLabel;updateSpeedLabel();
 $('#addProvider').onclick=()=>$('#providers').insertAdjacentHTML('beforeend',providerRow({name:'Provider',port:563,use_ssl:true,connections:8,enabled:true,priority:25}));
 $('#providers').onclick=async e=>{let rem=e.target.closest('[data-remove-provider]');if(rem){rem.closest('[data-provider]').remove();return}let test=e.target.closest('[data-test-provider]');if(!test)return;let r=test.closest('[data-provider]'),body={name:r.querySelector('[data-p=name]').value.trim(),host:r.querySelector('[data-p=host]').value.trim(),port:Number(r.querySelector('[data-p=port]').value||563),username:r.querySelector('[data-p=username]').value.trim(),password:r.querySelector('[data-p=password]').value.trim()||null,use_ssl:true,connections:Number(r.querySelector('[data-p=connections]').value||8),enabled:r.querySelector('[data-p=enabled]').value==='true',priority:Number(r.querySelector('[data-p=priority]').value||25)};test.disabled=true;try{let out=await api('/api/download-clients/native/test',post(body));notify(`Connected to ${out.provider} in ${out.latency_ms} ms.`,'ok')}catch(err){notify(err.message,'error')}finally{test.disabled=false}};
 $('#saveNative').onclick=async()=>{try{await api('/api/settings/native-usenet',patch({enabled:val('#nativeEnabled')==='true',providers:collectProviders(),incomplete_dir:val('#nativeIncomplete'),complete_dir:val('#nativeComplete'),max_connections:Number(val('#nativeConnections')),max_retries:Number(val('#nativeRetries')),speed_limit_mb_s:Number(val('#nativeSpeed')),repair_enabled:val('#nativeRepair')==='true',unpack_enabled:val('#nativeUnpack')==='true'}));notify('Built-in Usenet settings saved.','ok');settings()}catch(e){notify(e.message,'error')}};
}
async function renderMediaSettings(){let el=$('#settingsBody'),s=settingsCache.file_management,roots=await api('/api/root-folders'),root=roots.find(x=>x.is_default)||roots[0];el.innerHTML=`<div class="settings-panel"><h2>Media Management</h2><p>Scene root folder and file organization.</p><div class="formgrid"><div class="field"><label>File management</label><select id="fileEnabled"><option value="true" ${s.enabled?'selected':''}>Enabled</option><option value="false" ${!s.enabled?'selected':''}>Disabled</option></select></div><div class="field"><label>Import mode</label><select id="importMode">${['move','copy','hardlink'].map(x=>`<option ${s.import_mode===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field span2"><label>Scene root folder</label><input class="input" id="sceneRoot" value="${esc(root?.path||'')}"><span class="hint">Use an absolute path. On TrueNAS later, this will map to your media dataset.</span></div><div class="field span2"><label>Naming template</label><input class="input" id="sceneTemplate" value="${esc(s.scene_naming_template)}"></div><div class="field"><label>Recycle bin</label><input class="input" id="recycleBin" value="${esc(s.recycle_bin_path||'')}"></div><div class="field"><label>Minimum free space (GB)</label><input class="input" id="minFree" type="number" value="${s.minimum_free_space_gb}"></div></div><div class="divider"></div><button class="btn primary" id="saveMedia">Save Media Management</button></div>`;$('#saveMedia').onclick=async()=>{try{await api('/api/settings/file-management',patch({enabled:val('#fileEnabled')==='true',scene_naming_template:val('#sceneTemplate')}));await api('/api/settings/file-management/advanced',patch({import_mode:val('#importMode'),recycle_bin_path:val('#recycleBin'),minimum_free_space_gb:Number(val('#minFree'))}));let path=val('#sceneRoot');if(path){let body={name:'Scenes',content_type:'scene',path,is_default:true,create_missing:true};if(root)await api(`/api/root-folders/${root.id}`,put(body));else await api('/api/root-folders',post(body))}notify('Media management saved.','ok');settings()}catch(e){notify(e.message,'error')}}}
boot();
